"""Ledger entries: parsing, totals, filtering and formatting."""

import datetime
import decimal
import re
from dataclasses import dataclass
from decimal import Decimal

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(\.[0-9]{1,2})?")
_LINE_BREAK_RE = re.compile(r"\r\n|\r|\n")

# Exact arithmetic: the default context rounds at 28 significant digits.
_EXACT = decimal.Context(
    prec=decimal.MAX_PREC,
    Emax=decimal.MAX_EMAX,
    Emin=decimal.MIN_EMIN,
    traps=[decimal.InvalidOperation, decimal.DivisionByZero, decimal.Overflow],
)
_CENT = Decimal("0.01")


class ParseError(ValueError):
    """A line of the ledger is a mistake. ``line`` is its 1-based number."""

    def __init__(self, line, reason):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def parse_date(text):
    """Return the ``datetime.date`` for ``YYYY-MM-DD``; ValueError otherwise."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (expected YYYY-MM-DD)" % text)
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def parse_amount(text):
    """Return the ``Decimal`` for an amount with at most two decimals."""
    if not _AMOUNT_RE.fullmatch(text):
        raise ValueError("invalid amount %r (at most two decimals)" % text)
    return Decimal(text)


def parse(text):
    """Parse ledger text into a list of ``Entry`` in file order."""
    if text.startswith("﻿"):
        text = text[1:]
    entries = []
    for number, line in enumerate(_LINE_BREAK_RE.split(text), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        parts = stripped.split(None, 3)
        if len(parts) < 3:
            raise ParseError(number, "expected DATE CATEGORY AMOUNT [NOTE]")
        try:
            date = parse_date(parts[0])
            amount = parse_amount(parts[2])
        except ValueError as exc:
            raise ParseError(number, str(exc)) from None
        note = parts[3].strip() if len(parts) == 4 else ""
        entries.append(Entry(date, parts[1].lower(), amount, note))
    return entries


def balance(entries):
    """Total of all amounts (``Decimal``; zero when empty)."""
    total = Decimal(0)
    for entry in entries:
        total = _EXACT.add(total, entry.amount)
    return total


def _totals(entries, key):
    totals = {}
    for entry in entries:
        k = key(entry)
        totals[k] = _EXACT.add(totals.get(k, Decimal(0)), entry.amount)
    return totals


def by_category(entries):
    """Dict of category -> total."""
    return _totals(entries, lambda e: e.category)


def by_month(entries):
    """Dict of ``"YYYY-MM"`` -> total."""
    return _totals(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def filter_entries(entries, category=None, since=None, until=None):
    """Entries matching category (any case) and inclusive date bounds."""
    if category is not None:
        category = category.lower()
    result = []
    for entry in entries:
        if category is not None and entry.category != category:
            continue
        if since is not None and entry.date < since:
            continue
        if until is not None and entry.date > until:
            continue
        result.append(entry)
    return result


def format_amount(amount):
    """Amount with exactly two decimals; negative zero prints as 0.00."""
    q = amount.quantize(_CENT, context=_EXACT)
    if not q:
        q = q.copy_abs()
    return format(q, "f")


def format_entry(entry):
    """``DATE CATEGORY AMOUNT[ NOTE]``, as ``list`` prints it."""
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line
